from typing import List
from functools import lru_cache

def specialPerm(nums: List[int]):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute divisibility relation
    # can[i][j] = True if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
    can = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                a, b = nums[i], nums[j]
                if a % b == 0 or b % a == 0:
                    can[i][j] = True

    # DP with bitmask: dp[mask][last] = number of ways to arrange elements in mask, ending with element 'last'
    # mask is a bitmask of which elements have been used
    # last is the index of the last element used

    # Use iterative DP
    dp = [[0] * n for _ in range(1 << n)]

    # Base case: single element permutations
    for i in range(n):
        dp[1 << i][i] = 1

    # Fill DP table
    for mask in range(1, 1 << n):
        for last in range(n):
            if dp[mask][last] == 0:
                continue
            if not (mask & (1 << last)):
                continue
            # Try to add next element
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if can[last][nxt]:
                    new_mask = mask | (1 << nxt)
                    dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD

    # Sum up all full permutations (mask = (1 << n) - 1)
    full = (1 << n) - 1
    result = sum(dp[full][i] for i in range(n)) % MOD
    return result
