def specialPerm(nums: List[int]) -> int:
    MOD = 10**9 + 7
    n = len(nums)

    if n == 1:
        return 1

    # Build adjacency: which pairs are compatible
    # compatible[i][j] = True if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
    compatible = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    compatible[i][j] = True

    # Use bitmask DP
    # dp[mask][i] = number of ways to arrange the set of numbers represented by mask, ending with nums[i]
    # mask is a bitmask of size n
    # i is the index of the last element

    full_mask = (1 << n) - 1
    dp = [[0] * n for _ in range(1 << n)]

    # Initialize: single element arrangements
    for i in range(n):
        dp[1 << i][i] = 1

    # Iterate over all masks
    for mask in range(1 << n):
        for i in range(n):
            if dp[mask][i] == 0:
                continue
            if not (mask & (1 << i)):
                continue
            # Try to add a new element j that is not in mask and is compatible with i
            for j in range(n):
                if mask & (1 << j):
                    continue
                if compatible[i][j]:
                    new_mask = mask | (1 << j)
                    dp[new_mask][j] = (dp[new_mask][j] + dp[mask][i]) % MOD

    # Sum up all dp[full_mask][i] for all i
    result = 0
    for i in range(n):
        result = (result + dp[full_mask][i]) % MOD

    return result
