from typing import List

def specialPerm(nums: List[int]) -> int:
    n = len(nums)
    MOD = 10**9 + 7

    # Precompute divisibility relation
    # can[i][j] = True if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
    can = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                can[i][j] = (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0)

    # DP over subsets: dp[mask][last] = number of ways to arrange elements in mask ending with element 'last'
    # mask is a bitmask of n bits
    size = 1 << n
    dp = [[0]*n for _ in range(size)]

    # Initialize: single element permutations
    for i in range(n):
        dp[1 << i][i] = 1

    # Fill DP
    for mask in range(size):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            cur = dp[mask][last]
            if cur == 0:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if not can[last][nxt]:
                    continue
                new_mask = mask | (1 << nxt)
                dp[new_mask][nxt] = (dp[new_mask][nxt] + cur) % MOD

    # Sum all dp[full_mask][last] for all last
    full_mask = size - 1
    ans = sum(dp[full_mask]) % MOD
    return ans
