from typing import List

def numberOfSubmatrices(grid: List[List[str]]) -> int:
    m, n = len(grid), len(grid[0])

    # Build 2D prefix sum for X and Y
    # prefX[i][j] = count of 'X' in submatrix from (0,0) to (i-1, j-1)
    # prefY[i][j] = count of 'Y' in submatrix from (0,0) to (i-1, j-1)
    prefX = [[0] * (n + 1) for _ in range(m + 1)]
    prefY = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m):
        for j in range(n):
            prefX[i + 1][j + 1] = prefX[i][j + 1] + prefX[i + 1][j] - prefX[i][j] + (1 if grid[i][j] == 'X' else 0)
            prefY[i + 1][j + 1] = prefY[i][j + 1] + prefY[i + 1][j] - prefY[i][j] + (1 if grid[i][j] == 'Y' else 0)

    def countX(r1, c1, r2, c2):
        # r1, c1 top-left; r2, c2 bottom-right (inclusive)
        return prefX[r2 + 1][c2 + 1] - prefX[r1][c2 + 1] - prefX[r2 + 1][c1] + prefX[r1][c1]

    def countY(r1, c1, r2, c2):
        return prefY[r2 + 1][c2 + 1] - prefY[r1][c2 + 1] - prefY[r2 + 1][c1] + prefY[r1][c1]

    result = 0
    for r1 in range(m):
        for c1 in range(n):
            for r2 in range(r1, m):
                for c2 in range(c1, n):
                    x_count = countX(r1, c1, r2, c2)
                    y_count = countY(r1, c1, r2, c2)
                    if x_count == y_count and x_count >= 1:
                        result += 1

    return result
